import { useState } from 'react';
import type { ArtifactRef, InteractionSnapshot, NavigationTarget, ProcessClient } from '@wright/process-client';
import { ProcessUI, Section, ProgressPanel, ResultCard, ReasonNotice, WorkingControls } from '@wright/ui-kit';

export interface AppProps {
  client: ProcessClient;
  snapshot: InteractionSnapshot;
  readOnly: boolean;
}

export default function App({ client, snapshot, readOnly }: AppProps) {
  const [navigationFailed, setNavigationFailed] = useState(false);
  const navigate = (target: NavigationTarget) => {
    setNavigationFailed(false);
    void client.navigate(target).catch(() => setNavigationFailed(true));
  };
  const openEvidence = (reference: ArtifactRef) => navigate({
    kind: 'evidence', artifact_ref: reference.artifact_ref, result_id: reference.result_id,
  });

  return <ProcessUI>
    <Section title="Focus-wheel digital preparation">
      <p>Blender repair and independent slicing prepare a manufacturing package; validation and human engineering review determine its readiness.</p>
      {readOnly && <p>Preview — controls are read-only and do not change the process.</p>}
      <ProgressPanel state={snapshot.state} observations={snapshot.observations ?? []} />
      {(snapshot.diagnostics ?? []).map((reason, index) =>
        <ReasonNotice key={`${reason.code}-${index}`} reason={reason} />)}
      <WorkingControls client={client} snapshot={snapshot} readOnly={readOnly} onNavigate={navigate} />
      {navigationFailed && <p role="alert">Wright could not open this item. Use the common working view to inspect the exact process result.</p>}
    </Section>
    <Section title="Results and checks">
      {(snapshot.outputs ?? []).length === 0 && <p>Results will appear as the process produces them.</p>}
      {(snapshot.outputs ?? []).map(output =>
        <ResultCard key={output.result_id} output={output} onNavigate={navigate} onOpen={openEvidence} />)}
      <p>A dedicated representation viewer is not declared for this presentation. Open supported representations and exact evidence from their result cards.</p>
    </Section>
  </ProcessUI>;
}
